function isSameTree(p, q) {
  const queue = [[p, q]];
  while (queue.length > 0) {
    const [a, b] = queue.shift();
    if (a === null && b === null) continue;
    if (a === null || b === null || a.val !== b.val) return false;
    queue.push([a.left, b.left], [a.right, b.right]);       // straight pairs
  }
  return true;
}

