        TreeNode a = pair[0], b = pair[1];
        if (a == null && b == null) continue;
        if (a == null || b == null || a.val != b.val) return false;
        queue.offer(new TreeNode[]{a.left, b.right});    // crossed pairs
        queue.offer(new TreeNode[]{a.right, b.left});
    }
    return true;
}

